example:
service jobs from queue("jobs") {
    delivery { deadLetter: None }
    fallback { forward: "ops@ops.example" }   // ✗ not a `from email` service
    on message(job: String) -> Effect[QueueResult] by Producer { Ack }
}

service jobs from queue("jobs") {
    delivery { deadLetter: "jobs-dead" }   // ✓ a queue's counterpart
    on message(job: String) -> Effect[QueueResult] by Producer { Ack }
}
